library Strings {
bytes16 private constant _HEX_SYMBOLS = "0123456789abcdef";

function toString(uint256 value) internal pure returns (string memory) {

if (value == 0) {
return "0";
}
uint256 temp = value;
uint256 digits;
while (temp != 0) {
digits++;
temp /= 10;
}
bytes memory buffer = new bytes(digits);
while (value != 0) {
digits -= 1;
buffer[digits] = bytes1(uint8(48 + uint256(value % 10)));
value /= 10;
}
return string(buffer);
}

function toHexString(uint256 value) internal pure returns (string memory) {
if (value == 0) {
return "0x00";
}
uint256 temp = value;
uint256 length = 0;
while (temp != 0) {
length++;
temp >>= 8;
}
return toHexString(value, length);
}

function toHexString(uint256 value, uint256 length) internal pure returns (string memory) {
bytes memory buffer = new bytes(2 * length + 2);
buffer[0] = "0";
buffer[1] = "x";
for (uint256 i = 2 * length + 1; i > 1; --i) {
buffer[i] = _HEX_SYMBOLS[value & 0xf];
value >>= 4;
}
require(value == 0, "Strings: hex length insufficient");
return string(buffer);
}
}

abstract contract ERC165 is IERC165 {

function supportsInterface(bytes4 interfaceId) public view virtual override returns (bool) {
return interfaceId == type(IERC165).interfaceId;
}
}

contract ERC721 is Context, ERC165, IERC721, IERC721Metadata {
using Address for address;
using Strings for uint256;

string private _name;

string private _symbol;

mapping(uint256 => address) private _owners;

mapping(address => uint256) private _balances;

mapping(uint256 => address) private _tokenApprovals;

mapping(address => mapping(address => bool)) private _operatorApprovals;

constructor(string memory name_, string memory symbol_) {
_name = name_;
_symbol = symbol_;
}

function supportsInterface(bytes4 interfaceId) public view virtual override(ERC165, IERC165) returns (bool) {
return
interfaceId == type(IERC721).interfaceId ||
interfaceId == type(IERC721Metadata).interfaceId ||
super.supportsInterface(interfaceId);
}

function balanceOf(address owner) public view virtual override returns (uint256) {
require(owner != address(0), "ERC721: balance query for the zero address");
return _balances[owner];
}

function ownerOf(uint256 tokenId) public view virtual override returns (address) {
address owner = _owners[tokenId];
require(owner != address(0), "ERC721: owner query for nonexistent token");
return owner;
}

function name() public view virtual override returns (string memory) {
return _name;
}

function symbol() public view virtual override returns (string memory) {
return _symbol;
}

function tokenURI(uint256 tokenId) public view virtual override returns (string memory) {
require(_exists(tokenId), "ERC721Metadata: URI query for nonexistent token");

string memory baseURI = _baseURI();
return bytes(baseURI).length > 0 ? string(abi.encodePacked(baseURI, tokenId.toString())) : "";
}

function _baseURI() internal view virtual returns (string memory) {
return "";
}

function approve(address to, uint256 tokenId) public virtual override {
address owner = ERC721.ownerOf(tokenId);
require(to != owner, "ERC721: approval to current owner");

require(
_msgSender() == owner || isApprovedForAll(owner, _msgSender()),
"ERC721: approve caller is not owner nor approved for all"
);

_approve(to, tokenId);
}

function getApproved(uint256 tokenId) public view virtual override returns (address) {
require(_exists(tokenId), "ERC721: approved query for nonexistent token");

return _tokenApprovals[tokenId];
}

function setApprovalForAll(address operator, bool approved) public virtual override {
_setApprovalForAll(_msgSender(), operator, approved);
}

function isApprovedForAll(address owner, address operator) public view virtual override returns (bool) {
return _operatorApprovals[owner][operator];
}

function transferFrom(
address from,
address to,
uint256 tokenId
) public virtual override {

require(_isApprovedOrOwner(_msgSender(), tokenId), "ERC721: transfer caller is not owner nor approved");

_transfer(from, to, tokenId);
}

function safeTransferFrom(
address from,
address to,
uint256 tokenId
) public virtual override {
safeTransferFrom(from, to, tokenId, "");
}

function safeTransferFrom(
address from,
address to,
uint256 tokenId,
bytes memory _data
) public virtual override {
require(_isApprovedOrOwner(_msgSender(), tokenId), "ERC721: transfer caller is not owner nor approved");
_safeTransfer(from, to, tokenId, _data);
}

function _safeTransfer(
address from,
address to,
uint256 tokenId,
bytes memory _data
) internal virtual {
_transfer(from, to, tokenId);
require(_checkOnERC721Received(from, to, tokenId, _data), "ERC721: transfer to non ERC721Receiver implementer");
}

function _exists(uint256 tokenId) internal view virtual returns (bool) {
return _owners[tokenId] != address(0);
}

function _isApprovedOrOwner(address spender, uint256 tokenId) internal view virtual returns (bool) {
require(_exists(tokenId), "ERC721: operator query for nonexistent token");
address owner = ERC721.ownerOf(tokenId);
return (spender == owner || getApproved(tokenId) == spender || isApprovedForAll(owner, spender));
}

function _safeMint(address to, uint256 tokenId) internal virtual {
_safeMint(to, tokenId, "");
}

function _safeMint(
address to,
uint256 tokenId,
bytes memory _data
) internal virtual {
_mint(to, tokenId);
require(
_checkOnERC721Received(address(0), to, tokenId, _data),
"ERC721: transfer to non ERC721Receiver implementer"
);
}

function _mint(address to, uint256 tokenId) internal virtual {
require(to != address(0), "ERC721: mint to the zero address");
require(!_exists(tokenId), "ERC721: token already minted");

_beforeTokenTransfer(address(0), to, tokenId);

_balances[to] += 1;
_owners[tokenId] = to;

emit Transfer(address(0), to, tokenId);

_afterTokenTransfer(address(0), to, tokenId);
}

function _burn(uint256 tokenId) internal virtual {
address owner = ERC721.ownerOf(tokenId);

_beforeTokenTransfer(owner, address(0), tokenId);

_approve(address(0), tokenId);

_balances[owner] -= 1;
delete _owners[tokenId];

emit Transfer(owner, address(0), tokenId);

_afterTokenTransfer(owner, address(0), tokenId);
}

function _transfer(
address from,
address to,
uint256 tokenId
) internal virtual {
require(ERC721.ownerOf(tokenId) == from, "ERC721: transfer from incorrect owner");
require(to != address(0), "ERC721: transfer to the zero address");

_beforeTokenTransfer(from, to, tokenId);

_approve(address(0), tokenId);

_balances[from] -= 1;
_balances[to] += 1;
_owners[tokenId] = to;

emit Transfer(from, to, tokenId);

_afterTokenTransfer(from, to, tokenId);
}

function _approve(address to, uint256 tokenId) internal virtual {
_tokenApprovals[tokenId] = to;
emit Approval(ERC721.ownerOf(tokenId), to, tokenId);
}

function _setApprovalForAll(
address owner,
address operator,
bool approved
) internal virtual {
require(owner != operator, "ERC721: approve to caller");
_operatorApprovals[owner][operator] = approved;
emit ApprovalForAll(owner, operator, approved);
}

function _checkOnERC721Received(
address from,
address to,
uint256 tokenId,
bytes memory _data
) private returns (bool) {
if (to.isContract()) {
try IERC721Receiver(to).onERC721Received(_msgSender(), from, tokenId, _data) returns (bytes4 retval) {
return retval == IERC721Receiver.onERC721Received.selector;
} catch (bytes memory reason) {
if (reason.length == 0) {
revert("ERC721: transfer to non ERC721Receiver implementer");
} else {
assembly {
revert(add(32, reason), mload(reason))
}
}
}
} else {
return true;
}
}

function _beforeTokenTransfer(
address from,
address to,
uint256 tokenId
) internal virtual {}

function _afterTokenTransfer(
address from,
address to,
uint256 tokenId
) internal virtual {}
}

abstract contract ERC721URIStorage is ERC721 {
using Strings for uint256;

mapping(uint256 => string) private _tokenURIs;

function tokenURI(uint256 tokenId) public view virtual override returns (string memory) {
require(_exists(tokenId), "ERC721URIStorage: URI query for nonexistent token");

string memory _tokenURI = _tokenURIs[tokenId];
string memory base = _baseURI();

if (bytes(base).length == 0) {
return _tokenURI;
}

if (bytes(_tokenURI).length > 0) {
return string(abi.encodePacked(base, _tokenURI));
}

return super.tokenURI(tokenId);
}

function _setTokenURI(uint256 tokenId, string memory _tokenURI) internal virtual {
require(_exists(tokenId), "ERC721URIStorage: URI set of nonexistent token");
_tokenURIs[tokenId] = _tokenURI;
}

function _burn(uint256 tokenId) internal virtual override {
super._burn(tokenId);

if (bytes(_tokenURIs[tokenId]).length != 0) {
delete _tokenURIs[tokenId];
}
}
}

abstract contract Ownable is Context {
address private _owner;

event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

constructor() {
_transferOwnership(_msgSender());
}

function owner() public view virtual returns (address) {
return _owner;
}

modifier onlyOwner() {
require(owner() == _msgSender(), "Ownable: caller is not the owner");
_;
}

function renounceOwnership() public virtual onlyOwner {
_transferOwnership(address(0));
}

function transferOwnership(address newOwner) public virtual onlyOwner {
require(newOwner != address(0), "Ownable: new owner is the zero address");
_transferOwnership(newOwner);
}

function _transferOwnership(address newOwner) internal virtual {
address oldOwner = _owner;
_owner = newOwner;
emit OwnershipTransferred(oldOwner, newOwner);
}
}

library Counters {
struct Counter {

uint256 _value;
}

function current(Counter storage counter) internal view returns (uint256) {
return counter._value;
}

function increment(Counter storage counter) internal {
unchecked {
counter._value += 1;
}
}

function decrement(Counter storage counter) internal {
uint256 value = counter._value;
require(value > 0, "Counter: decrement overflow");
unchecked {
counter._value = value - 1;
}
}

function reset(Counter storage counter) internal {
counter._value = 0;
}
}

contract FlippazOne is ERC721, ERC721URIStorage, Ownable {
using Counters for Counters.Counter;

Counters.Counter private _tokenIdCounter;

string public baseURI;
address public proxyRegistryAddress;

uint256 public constant MAX_SUPPLY = 1;
uint256 public minBidStep = 0.25 ether;

uint256 public constant buyNowPrice = 15 ether;
uint256 public constant buyNowPriceUntilBid = 14.75 ether;
uint256 public buyNowMultiplier = 20;
bool public boughtNow;

uint256 public auctionDuration = 24 hours;
bool public auctionStarted;
uint256 public auctionStartTimestamp;
bool public auctionEnded;
uint256 public auctionEndTimestamp;

uint256 public highestBid = 0.9 ether;
address public highestBidder;
uint256 public totalSupply = 0;

mapping(address => uint) public bids;
mapping(address => bool) public projectProxy;

mapping(address => bool) public hasAddressBidded;
address[] bidAdresses;
uint256 totalBidAddresses;

constructor() ERC721("FlippazOne", "FlippazOne") {
proxyRegistryAddress = 0xa5409ec958C83C3f309868babACA7c86DCB077c1;
baseURI = "ipfs:
}

function _baseURI() internal view override returns (string memory) {
return baseURI;
}

function editBaseUri(string memory newUri) public onlyOwner{
baseURI = newUri;
}

function editBuyNowMultipler(uint256 newMultiplier) public onlyOwner{
buyNowMultiplier = newMultiplier;
}

function editMinBidStep(uint256 newMinBidStep) public onlyOwner{
minBidStep = newMinBidStep;
}

function editDuration(uint256 newDuration) public onlyOwner{
require(auctionStarted, "Auction has not yet been started");
auctionEndTimestamp = auctionStartTimestamp + newDuration;
auctionDuration = newDuration;
}

function isAuctionActive() public view returns(bool){
if (auctionStarted){
if (!auctionEnded){
return block.timestamp < auctionEndTimestamp;
}
}
return false;
}

function startAuction() public onlyOwner{
require(auctionStarted == false, "Auction is already started");
auctionStarted = true;
auctionStartTimestamp = block.timestamp;
auctionEndTimestamp = block.timestamp + auctionDuration;
}

function getBidderPaidAmount(address bidder) public view returns(uint256){
return bids[bidder];
}

function getBidderByIndex(uint256 bidderIndex) public view returns(address){
return bidAdresses[bidderIndex];
}

function bid() public payable {
require(auctionStarted, "Auction has not yet started");
require(!auctionEnded, "Auction has been finished");
require(!boughtNow, "Auction has been finished");
require(block.timestamp < auctionEndTimestamp, "Auction has been finished");

uint256 newBid = bids[_msgSender()] + msg.value;
require(newBid >= highestBid + minBidStep, "Bid must be at least 0.25 ETH higher than the highest bid");

bids[_msgSender()] += msg.value;
highestBid = newBid;
highestBidder = _msgSender();

if (!hasAddressBidded[_msgSender()]){
hasAddressBidded[_msgSender()] = true;
totalBidAddresses++;
bidAdresses.push(_msgSender());
}

}

function isBuyNowActive() public view returns(bool){
if (auctionStarted){
if (!auctionEnded){
if (!boughtNow){
if (block.timestamp < auctionEndTimestamp){
return true;
}
}
}
}
return false;
}

function getBuyNowPrice() public view returns(uint256){
if (highestBid < buyNowPriceUntilBid){
return buyNowPrice;
} else {
uint256 newBuyNowPrice = highestBid * buyNowMultiplier / 10;
return newBuyNowPrice;
}
}

function buyNow() public payable {
require(auctionStarted, "Auction has not yet started");
require(!auctionEnded, "Auction has been finished");
require(block.timestamp < auctionEndTimestamp, "Auction has been finished");
require(!boughtNow, "Sorry! Somebody already used BUY NOW button");
uint256 currentBuyPrice = getBuyNowPrice();
require(msg.value == currentBuyPrice - bids[_msgSender()], "Invalid funds provided");

highestBid = currentBuyPrice;
highestBidder = _msgSender();

uint256 tokenId = _tokenIdCounter.current();
_tokenIdCounter.increment();
_mint(_msgSender(), tokenId);
boughtNow = true;
auctionEnded = true;
totalSupply = 1;
}

function endAuction() public {
require(auctionStarted, "Auction has not yet started");
require(!auctionEnded, "You cannot end the action again");
require(block.timestamp >= auctionEndTimestamp, "Auction duration has not yet elapsed");
uint256 tokenId = _tokenIdCounter.current();
_tokenIdCounter.increment();

if (highestBidder != address(0)){
_safeMint(highestBidder, tokenId);
} else {
_safeMint(owner(), tokenId);
}
totalSupply = 1;
auctionEnded = true;
}

function refundBids() public {
require(auctionEnded, "Please end the auction firstly");
for (uint256 i = 0; i < totalBidAddresses; i++){
uint256 addressTotalBid = bids[bidAdresses[i]];
if ((addressTotalBid > 0) && (bidAdresses[i] != highestBidder)){
(bool success, ) = bidAdresses[i].call{value: addressTotalBid}("");
bids[bidAdresses[i]] = 0;
}
}
}

function burn(uint256 tokenId) public {
require(_isApprovedOrOwner(_msgSender(), tokenId), "Not approved to burn.");
_burn(tokenId);
}

function ownerWithdraw() public {
require(auctionEnded || block.timestamp > auctionEndTimestamp, "Cannot withdraw until auction is ended");
(bool success, ) = owner().call{value: highestBid}("");
require(success, "Failed to withdraw funds.");
}

function ownerWithdrawTo(address toAddress) public {
require(auctionEnded || block.timestamp > auctionEndTimestamp, "Cannot withdraw until auction is ended");
(bool success, ) = toAddress.call{value: highestBid}("");
require(success, "Failed to withdraw funds.");
}

function ownerWithdrawAll() public {
(bool success, ) = owner().call{value: address(this).balance}("");
require(success, "Failed to withdraw funds.");
}

function ownerWithdrawAllTo(address toAddress) public {
(bool success, ) = toAddress.call{value: address(this).balance}("");
require(success, "Failed to withdraw funds.");
}

function bidderWithdraw() public {
uint256 totalBid = getBidderPaidAmount(_msgSender());
require(totalBid > 0, "Nothing to withdraw");
require(highestBidder != _msgSender(), "You cannot withdraw as your bid is the highest bid");
(bool success, ) = _msgSender().call{value: totalBid}("");
require(success, "Failed to withdraw funds.");
bids[_msgSender()] = 0;
}

function _burn(uint256 tokenId) internal override(ERC721, ERC721URIStorage) {
super._burn(tokenId);
}

function tokenURI(uint256 tokenId)
public
view
override(ERC721, ERC721URIStorage)
returns (string memory)
{
require(_exists(tokenId), "Token does not exist");
return _baseURI();
}

function isApprovedForAll(address _owner, address operator) public view override(ERC721) returns (bool) {
OpenSeaProxyRegistry proxyRegistry = OpenSeaProxyRegistry(proxyRegistryAddress);
if (address(proxyRegistry.proxies(_owner)) == operator || projectProxy[operator]) return true;
return super.isApprovedForAll(_owner, operator);
}
}

contract OwnableDelegateProxy { }

contract OpenSeaProxyRegistry {
mapping(address => OwnableDelegateProxy) public proxies;
}
```

## Fuzzing task — strategy: logic_error_probe

**Objective:** Build a transaction sequence in which the attacker-controlled address (attacker_address) ends up with more total value (native coin + tokens) than it spent — i.e. extract funds from the target or break a value invariant in the attacker's favor. Use at most 12 calls per sequence.

**Goal:** Find broken-invariant and faulty-accounting logic errors.

**Technique:**
Hunt for functions that MOVE FUNDS OR SHARES based on a check that may be wrong, missing, or inverted. High-yield patterns in THIS ABI:
  1. NON-PARTICIPANT WITHDRAW: call withdraw*/unstake*/redeem*/claim* as an account that NEVER deposited or staked — a bad balance check (or an underflow on a zero balance) can still pay out or corrupt accounting.
  2. INVERTED / WRONG GUARD: try threshold args that a correct '>=' / '<=' would reject (e.g. amount == balance, amount just over balance) to expose inverted comparisons.
  3. BROKEN INVARIANT: for pool/AMM-style targets, drive swap*/skim*/sync* so a constant-product (K) or reserve invariant is checked AFTER the imbalance, not before.
  4. ORDER-DEPENDENT STATE: sequence setter→action→setter→action, init-after-use, deposit-after-withdraw, to reach states the developer didn't anticipate.
The witness is value gained without legitimate entitlement. DO NOT default to the names in the example below.

**Value hints:** Use moderate hex values like "0x64", "0x3e8" for state changes. Use large values like "0xde0b6b3a7640000" for deposits/withdraw amounts. Try amounts at or just above a balance to hit inverted guards.

**Valid callers:** "attacker_address"
Use only these alias name(s) in the `caller_name` (msg.sender) slot — there is a
single attacker identity, so every call already runs as the attacker. Never use
"deployer_address" or a raw hex address as a caller. (Address-TYPED ARGUMENTS are
separate: see "Special argument values" below for the aliases those slots accept —
you are NOT restricted to the caller alias there.)
**Special argument values:**
- address-typed args accept `target_address`, `attacker_address`, or a raw 0x literal.
- `"max"` → uint256 max; `"now"` → block.timestamp.
- `"$ret<idx>"` → feed the RETURN VALUE of the call at 0-based index <idx> in this sequence into this argument (that call must return exactly one value).

**Argument encoding (match each value to its ABI parameter type):**
- uint* / bytesN / bytes → hex string, e.g. "0x1f" (minimal, not zero-padded)
- int* (signed) → decimal string, e.g. "-5"
- bool → true or false (JSON literal, unquoted)
- address → an alias name (see callers/aliases above) or a 40-hex-digit 0x literal
- arrays → JSON list, e.g. [] or ["0x1", "0x2"]; tuples/structs → JSON list of their fields
- empty bytes / empty signature / empty proof → "0x" or []

**Output format:**
Return a JSON array of 1 fuzz input object(s):
[
  {
    "calls": [["functionName", [arg1, arg2], "0x<wei_hex>", "caller_name"], ...],
    "description": "brief description"
  }
]
JSON only — no markdown, no explanation.

**Example sequence:**
```json
Structural pattern (replace UPPERCASE placeholders with real ABI function names):
  [["<WITHDRAW_OR_UNSTAKE_FROM_ABI>", ["0xde0b6b3a7640000"], "0x0", "attacker_address"],
   ["<SWAP_OR_ACTION_FUNC_FROM_ABI>", ["0x0", "0xde0b6b3a7640000"], "0x0", "attacker_address"],
   ["<DEPENDENT_EXTRACTOR_FROM_ABI>", [], "0x0", "attacker_address"]]
```

